#!/usr/bin/env python
"""Is `records/INDEX.md` what Arbiter would generate from the ledger right now?

    python scripts/check_index.py          # exit 1 if INDEX.md is stale (CI)
    python scripts/check_index.py --write  # regenerate it

⛔ **Why this exists (2026-11-12 structure review).** `records/README.md` says INDEX.md is
"generated by Arbiter; do not edit by hand", but nothing regenerated it or compared it. It had
drifted to 50 rows against 67 artifacts — 15 SPECs and two ADRs missing, three with the wrong
status — and one row had been added by hand. The index is the one status view of the ledger.

It used to be unsafe to regenerate: `Ledger.index()` calls `Ledger.status()`, which rewrote SPEC
files it found tampered. SPEC-arbiter-status-is-read-only made `status()` read-only, and CI pins
an Arbiter commit that includes it, so regeneration only writes INDEX.md.
"""

from __future__ import annotations

import argparse
import difflib
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
RECORDS = ROOT / "records"


def generate(records: Path) -> str:
    """The INDEX.md text Arbiter generates for ``records`` (written to disk as a side effect)."""
    from khala.arbiter.ledger import Ledger

    for d in ("specs", "adr", ".reviews"):
        if not (records / d).is_dir():
            raise SystemExit(f"refused: {records / d} is missing — not generating a new ledger")
    return Ledger(records, now=lambda: "").index().read_text(encoding="utf-8")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--write", action="store_true", help="regenerate INDEX.md instead of checking")
    ap.add_argument("--records", type=Path, default=RECORDS)
    a = ap.parse_args(argv)
    # INDEX.md carries emoji headings; a Windows console codepage cannot print them.
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")

    index = a.records / "INDEX.md"
    before = index.read_text(encoding="utf-8") if index.exists() else ""
    after = generate(a.records)
    if a.write or after == before:
        print("✓ records/INDEX.md matches the ledger" if after == before
              else "✓ records/INDEX.md regenerated")
        return 0
    index.write_text(before, encoding="utf-8", newline="\n")  # a check must not edit the evidence
    sys.stdout.writelines(difflib.unified_diff(
        before.splitlines(keepends=True), after.splitlines(keepends=True),
        "records/INDEX.md (committed)", "records/INDEX.md (generated)"))
    print("\n⛔ records/INDEX.md is stale — "
          "run `python scripts/check_index.py --write` and commit it")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
